INSERT INTO facts(id,keywords,title,content,source,updated_at) VALUES('mayor-official','역대 군수 태안군수 역대군수 명단 몇대 군수 계보','태안군 역대 군수(공식)','태안군 역대 군수(태안군청 열린군수실 공식): 1대 조철행(1989.1.1~1989.11.8), 2대 유응상(1989.11.9~1991.1.13), 3대 권오창(1991.1.14~1992.7.3), 4대 이종은(1992.7.4~1994.1.3), 5대 송성현(1994.1.4~1994.10.6), 6대 김경년(1994.10.7~1995.6.30), 7~8대 윤형상(1995.7.1~2002.6.30), 9~10대 진태구(2002.7.2~2010.6.30), 11대 김세호(2010.7.1~2011.3.24), 12대 진태구(2011.4.27~2014.6.30), 13대 한상기(2014.7.1~2018.6.30), 14~15대 가세로(2018.7.1~2026.6.30), 16대 윤희신(2026.7.1~). (1~5대는 관선, 6대부터 민선)','태안군청 열린군수실','2026-07-30T12:30:00.000Z') ON CONFLICT(id) DO UPDATE SET keywords=excluded.keywords,title=excluded.title,content=excluded.content,source=excluded.source,updated_at=excluded.updated_at;
